        if (key === 'set-cookie') {
          responseHeaders.append(key, value)
        } else {
          responseHeaders.set(key, value)
        }
      }
    }

    if (headers) {
      if (!responseHeaders) {
        let count = 0
        for (const k in headers) {
          if (++count > 1 || typeof headers[k as keyof HeaderRecord] !== 'string') {
            responseHeaders = new Headers()
            break
          }
        }
